    &&& stub.instance_id() == log.id()
    // ensures ssm.IsStub(rid, output, stub.val)  -> (exists ctail, op, nodeid :: stub == ReadOp(rid, ReadonlyDone(op, output, nodeid, ctail)))

    &&& stub.key() == rid
    &&& stub.value().is_Done()
    &&& stub.value().get_Done_ret() == result
}

