        match self {
            ReadonlyState::Init { op, .. } => op,
            ReadonlyState::VersionUpperBound { op, .. } => op,
            ReadonlyState::ReadyToRead { op, .. } => op,
            ReadonlyState::Done { op, .. } => op,
        }
    }
}

